def canonical(shape):
 forms=[]
 for k in range(4):
  pts=list(shape)
  # each flip/reflection rotations from original
  for flip in (1,-1):
   arr=[(x, y*flip) for x,y in pts]
   for _ in range(k): arr=[(y,-x) for x,y in arr]
   a=min(x for x,y in arr);b=min(y for x,y in arr)
   forms.append(frozenset((x-a,y-b) for x,y in arr))
 return min(tuple(sorted(s)) for s in forms)
